file.content:
.message-bubble {
  padding: 10px 14px;
  border-radius: 10px;
  margin-bottom: 10px;
}

.message-bubble--user {
  background: #eef2ff;
  margin-left: 32px;
}

.message-bubble--assistant {
  background: #fff;
  border: 1px solid #e5e7eb;
  margin-right: 32px;
}

.message-bubble__header {
  font-size: 11px;
  font-weight: 600;
  color: #6b7280;
  margin-bottom: 4px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.message-bubble__content {
  font-size: 14px;
  line-height: 1.5;
  color: #1f2937;
}

.message-bubble__content p {
  margin: 0 0 8px;
}

.message-bubble__content p:last-child {
  margin-bottom: 0;
}

.message-bubble__content pre {
  background: #f3f4f6;
  padding: 8px 12px;
  border-radius: 6px;
  overflow-x: auto;
  font-size: 12px;
}

.message-bubble__content code {
  background: #f3f4f6;
  padding: 1px 4px;
  border-radius: 3px;
  font-size: 13px;
}

.message-bubble__content pre code {
  background: none;
  padding: 0;
}

.message-bubble__content table {
  border-collapse: collapse;
  width: 100%;
  margin: 8px 0;
  font-size: 13px;
  overflow-x: auto;
  display: block;
}

.message-bubble__content th,
.message-bubble__content td {
  border: 1px solid #d1d5db;
  padding: 6px 10px;
  text-align: left;
  white-space: nowrap;
}

.message-bubble__content th {
  background: #f3f4f6;
  font-weight: 600;
}

.message-bubble__content tr:nth-child(even) {
  background: #f9fafb;
}

.message-bubble__typing {
  color: #9ca3af;
  font-style: italic;
}

.message-bubble__tools {
  margin-top: 8px;
}

/* Segments layout */
.message-bubble__segments {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.message-bubble__segment {
  border-radius: 6px;
  padding: 8px 12px;
}

.message-bubble__segment--thinking {
  background: #f9fafb;
  border-left: 3px solid #d1d5db;
}

.message-bubble__segment--answer {
  background: #f0fdf4;
  border-left: 3px solid #22c55e;
}

.message-bubble__segment-label {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #9ca3af;
  margin-bottom: 4px;
}

.message-bubble__segment-label--answer {
  color: #16a34a;
}

.message-bubble__segment-content {
  font-size: 14px;
  line-height: 1.5;
  color: #1f2937;
}

.message-bubble__segment-content p {
  margin: 0 0 8px;
}

.message-bubble__segment-content p:last-child {
  margin-bottom: 0;
}

.message-bubble__segment-content pre {
  background: #f3f4f6;
  padding: 8px 12px;
  border-radius: 6px;
  overflow-x: auto;
  font-size: 12px;
}

.message-bubble__segment-content code {
  background: #f3f4f6;
  padding: 1px 4px;
  border-radius: 3px;
  font-size: 13px;
}

.message-bubble__segment-content pre code {
  background: none;
  padding: 0;
}

.message-bubble__segment-content table {
  border-collapse: collapse;
  width: 100%;
  margin: 8px 0;
  font-size: 13px;
  overflow-x: auto;
  display: block;
}

.message-bubble__segment-content th,
.message-bubble__segment-content td {
  border: 1px solid #d1d5db;
  padding: 6px 10px;
  text-align: left;
  white-space: nowrap;
}

.message-bubble__segment-content th {
  background: #f3f4f6;
  font-weight: 600;
}

.message-bubble__segment-content tr:nth-child(even) {
  background: #f9fafb;
}

/* Collapsible thinking segments */
.message-bubble__collapsible {
  cursor: default;
}

.message-bubble__collapsible-summary {
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  list-style: none;
  user-select: none;
}

.message-bubble__collapsible-summary::-webkit-details-marker {
  display: none;
}

.message-bubble__collapsible-summary::before {
  content: '▶';
  font-size: 9px;
  color: #9ca3af;
  transition: transform 0.15s ease;
  flex-shrink: 0;
}

.message-bubble__collapsible[open] > .message-bubble__collapsible-summary::before {
  transform: rotate(90deg);
}

.message-bubble__collapsible-summary .message-bubble__segment-label {
  margin-bottom: 0;
  flex-shrink: 0;
}

.message-bubble__collapsible-preview {
  font-size: 12px;
  color: #9ca3af;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}

.message-bubble__collapsible[open] > .message-bubble__collapsible-summary .message-bubble__collapsible-preview {
  display: none;
}

.message-bubble__thinking-body {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 8px;
}

.message-bubble__tool-segment {
  margin: 2px 0;
}

